//! The persisted task entity.

use chrono::{DateTime, Utc};
use uuid::Uuid;

use super::fields::{DueDate, TaskDescription, TaskPriority, TaskStatus, TaskTitle};

/// Identifier of a task. Generated by the database on creation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TaskId(Uuid);

impl TaskId {
    pub fn new(value: Uuid) -> Self {
        Self(value)
    }

    pub fn value(self) -> Uuid {
        self.0
    }
}

/// A stored task. Only built from persisted parts; creation input goes
/// through `NewTask`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Task {
    id: TaskId,
    title: TaskTitle,
    description: Option<TaskDescription>,
    status: TaskStatus,
    priority: TaskPriority,
    due_date: Option<DueDate>,
    created_at: DateTime<Utc>,
    updated_at: DateTime<Utc>,
}

/// Persisted parts of a task, used to rehydrate the entity.
#[derive(Debug, Clone)]
pub struct TaskParts {
    pub id: TaskId,
    pub title: TaskTitle,
    pub description: Option<TaskDescription>,
    pub status: TaskStatus,
    pub priority: TaskPriority,
    pub due_date: Option<DueDate>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

impl Task {
    pub fn restore(parts: TaskParts) -> Self {
        Self {
            id: parts.id,
            title: parts.title,
            description: parts.description,
            status: parts.status,
            priority: parts.priority,
            due_date: parts.due_date,
            created_at: parts.created_at,
            updated_at: parts.updated_at,
        }
    }

    pub fn id(&self) -> TaskId {
        self.id
    }

    pub fn title(&self) -> &TaskTitle {
        &self.title
    }

    pub fn description(&self) -> Option<&TaskDescription> {
        self.description.as_ref()
    }

    pub fn status(&self) -> TaskStatus {
        self.status
    }

    pub fn priority(&self) -> TaskPriority {
        self.priority
    }

    pub fn due_date(&self) -> Option<DueDate> {
        self.due_date
    }

    pub fn created_at(&self) -> DateTime<Utc> {
        self.created_at
    }

    pub fn updated_at(&self) -> DateTime<Utc> {
        self.updated_at
    }
}
